def interpolacion_lagrange(muestra, x):
    resultado = 0.0
    for xi, yi in muestra:
        termino = yi
        for xj, _ in muestra:
            if xj != xi:
                termino *= (x - xj) / (xi - xj)
        resultado += termino
    return resultado
```

