from functools import lru_cache

def min_insertions(s):
    @lru_cache(maxsize=None)
    def helper(i, j):
        if i >= j:
            return 0
        if s[i] == s[j]:
            return helper(i + 1, j - 1)
        else:
            return 1 + min(helper(i + 1, j), helper(i, j - 1))

    return helper(0, len(s) - 1)
```

