import sys

def are_colinear(a, b, c):
    # Check if three points a, b, c are colinear
    return (b[0] - a[0]) * (c[1] - a[1]) == (b[1] - a[1]) * (c[0] - a[0])

def main():
    n = int(sys.stdin.readline())
    if n <= 2:
        print("YES")
        return
    points = [tuple(map(int, sys.stdin.readline().split())) for _ in range(n)]
    a = points[0]
    b = points[1]
    all_colinear_initial = True
    for p in points[2:]:
        if not are_colinear(a, b, p):
            all_colinear_initial = False
            break
    if all_colinear_initial:
        print("YES")
        return

    # Check if first three points are colinear
    c = points[2]
    first_three_colinear = are_colinear(a, b, c)
    if first_three_colinear:
        # All on line AB, check the rest
        S = []
        for p in points:
            if not are_colinear(a, b, p):
                S.append(p)
        if len(S) <= 1:
            print("YES")
            return
        else:
            s0 = S[0]
            s1 = S[1]
            for p in S[2:]:
                if not are_colinear(s0, s1, p):
                    print("NO")
                    return
            print("YES")
            return
    else:
        # Check three possible line candidates
        candidates = [(a, b), (a, c), (b, c)]
        for (line_a, line_b) in candidates:
            S = []
            for p in points:
                if not are_colinear(line_a, line_b, p):
                    S.append(p)
            if len(S) <= 1:
                print("YES")
                return
            # Check if all in S are colinear
            s0 = S[0]
            s1 = S[1]
            valid = True
            for p in S:
                if not are_colinear(s0, s1, p):
                    valid = False
                    break
            if valid:
                print("YES")
                return
        print("NO")
        return

if __name__ == "__main__":
    main()
```

(a) To prove that all Mozartian numbers are even, we consider the total number of digits from 1 to \( n \). If \( n \) is odd, the total number of digits is odd. Since the sum of even counts (required for a Mozartian number) must be even, an odd total number of digits implies at least one digit must have an odd count. Hence, \( n \) cannot be Mozartian. Therefore, all Mozartian numbers must be even.

(b) To prove there are infinitely many Mozartian numbers, observe that digit count parities (even/odd) cycle through finite combinations. By the Pigeonhole Principle, some parity combination repeats infinitely often. Since we can adjust even numbers to balance digit counts, there must be infinitely many even \( n \) where all digit counts are even. Hence, infinitely many Mozartian numbers exist.


(a) \boxed{\text{All Mozartian numbers are even.}}

(b) \boxed{\text{There are infinitely many Mozartian numbers.}}

