def compute_function(dimension, values, operation):
    if operation == "add":
        function_value = sum(values)
        gradient = [1.0] * dimension
    elif operation == "mul":
        product = 1
        for v in values:
            product *= v
        function_value = product
        gradient = []
        for i in range(dimension):
            g = 1
            for j in range(dimension):
                if j != i:
                    g *= values[j]
            gradient.append(g)
    elif operation == "pow":
        function_value = values[0] ** 2
        gradient = [2 * values[0]] + [0.0] * (dimension - 1)
    else:
        raise ValueError("Invalid operation")

    return {
        "function_value": function_value,
        "gradient": gradient
    }
```

