def max_sublist_sum(nums, k):
    if k <= 0 or len(nums) < k:
        return 0
    current_sum = sum(nums[:k])
    max_sum = current_sum
    for i in range(k, len(nums)):
        current_sum += nums[i] - nums[i - k]
        if current_sum > max_sum:
            max_sum = current_sum
    return max_sum
```

