from collections import deque

def topological_order(numVertexes, numEdges, edges):
    adjacency = [[] for _ in range(numVertexes)]
    in_degree = [0] * numVertexes

    for u, v in edges:
        adjacency[u].append(v)
        in_degree[v] += 1

    queue = deque()
    for i in range(numVertexes):
        if in_degree[i] == 0:
            queue.append(i)

    topological_order = []
    while queue:
        node = queue.popleft()
        topological_order.append(str(node))
        for neighbor in adjacency[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(topological_order) == numVertexes:
        return topological_order
    else:
        return "Graph has a cycle"
```

