def solve_tic_tac_toe(state, turn):
    state = state.copy()

    def is_terminal(s):
        # Check rows
        for i in range(0, 9, 3):
            if s[i] != '0' and s[i] == s[i+1] == s[i+2]:
                return True
        # Check columns
        for i in range(3):
            if s[i] != '0' and s[i] == s[i+3] == s[i+6]:
                return True
        # Check diagonals
        if s[0] != '0' and s[0] == s[4] == s[8]:
            return True
        if s[2] != '0' and s[2] == s[4] == s[6]:
            return True
        # Check if board is full
        if '0' not in s:
            return True
        return False

    def compute_utility(s):
        # Check for X win
        for i in range(0, 9, 3):
            if s[i] == 'x' and s[i] == s[i+1] == s[i+2]:
                return 1
        for i in range(3):
            if s[i] == 'x' and s[i] == s[i+3] == s[i+6]:
                return 1
        if s[0] == 'x' and s[0] == s[4] == s[8]:
            return 1
        if s[2] == 'x' and s[2] == s[4] == s[6]:
            return 1
        # Check for O win
        for i in range(0, 9, 3):
            if s[i] == 'o' and s[i] == s[i+1] == s[i+2]:
                return -1
        for i in range(3):
            if s[i] == 'o' and s[i] == s[i+3] == s[i+6]:
                return -1
        if s[0] == 'o' and s[0] == s[4] == s[8]:
            return -1
        if s[2] == 'o' and s[2] == s[4] == s[6]:
            return -1
        # Draw
        return 0

    def minimax(s, current_turn):
        if is_terminal(s):
            return compute_utility(s), None
        best_val = -float('inf') if current_turn == 'x' else float('inf')
        best_move = None
        next_turn = 'o' if current_turn == 'x' else 'x'
        for i in range(9):
            if s[i] == '0':
                new_s = s.copy()
                new_s[i] = current_turn
                child_val, _ = minimax(new_s, next_turn)
                if current_turn == 'x':
                    if child_val > best_val:
                        best_val = child_val
                        best_move = new_s
                else:
                    if child_val < best_val:
                        best_val = child_val
                        best_move = new_s
        return best_val, best_move

    utility, best_move_state = minimax(state, turn)
    if best_move_state is None:
        best_move = state.copy()
    else:
        best_move = best_move_state
    return {
        'utility_value': utility,
        'best_move': best_move
    }
```

