```python
def solution(constraints):
    parent = {}
    rank = {}

    def find(x):
        if x not in parent:
            parent[x] = x
            rank[x] = 1
        if parent[x] != x:
            parent[x] = find(parent[x])  # Path compression
        return parent[x]

    def union(x, y):
        x_root = find(x)
        y_root = find(y)
        if x_root == y_root:
            return
        # Union by rank
        if rank[x_root] < rank[y_root]:
            parent[x_root] = y_root
        else:
            parent[y_root] = x_root
            if rank[x_root] == rank[y_root]:
                rank[x_root] += 1

    equal_constraints = []
    not_equal_constraints = []

    for constraint in constraints:
        if '=' in constraint:
            x, y = constraint.split('=', 1)
            equal_constraints.append((x, y))
        else:
            x, y = constraint.split('!', 1)
            not_equal_constraints.append((x, y))

    # Process all equality constraints first
    for x, y in equal_constraints:
        union(x, y)

    # Check all not-equal constraints
    can_be_satisfied = True
    for x, y in not_equal_constraints:
        if find(x) == find(y):
            can_be_satisfied = False
            break

    return {"can_be_satisfied": can_be_satisfied}
```

