    count = 0
    for line in input_lines:
        outside_parts = []
        parts = line.split('[')
        if parts:
            outside_parts.append(parts[0])
        for part in parts[1:]:
            bracket_split = part.split(']', 1)
            if len(bracket_split) == 2:
                outside_part = bracket_split[1]
                outside_parts.append(outside_part)
        abba_found = False
        for s in outside_parts:
            for i in range(len(s) - 3):
                a, b, c, d = s[i], s[i+1], s[i+2], s[i+3]
