    i = j = 0
    while i < len(s1) and j < len(s2):
        if s1[i] > s2[j]:
            result.append(s1[i])
            i += 1
        elif s1[i] < s2[j]:
            result.append(s2[j])
            j += 1
        else:
            if s1[i:] > s2[j:]:
                result.append(s1[i])
                i += 1
            else:
                result.append(s2[j])
                j += 1
    result.append(s1[i:])
    result.append(s2[j:])
