# import necessary packages
import random

# all class and function definitions in the code file, if any
class Graph:
    def __init__(self, n):
        self._n = n
        self._adj = [set() for _ in range(n)]

    def add_edge(self, u, v):
        self._adj[u].add(v)

    def next_to(self, v):
        return self._adj[v]

    def is_connected(self, u, v):
        return v in self.next_to(u)

    def vertices(self):
        return range(self.size())

    def edges(self):
        return [(u, v) for u in self.vertices() for v in self.next_to(u)]

    def size(self):
        return self._n

    @classmethod
    def make_random(cls, n, p):
        self = cls(n)
        for u in range(n):
            for v in range(n):
                if u != v and random.random() < p:
                    self.add_edge(u, v)
        return self

    @classmethod
    def make_random_fix(cls, n, e):
        self = cls(n)
        for u, v in random_permutations(n, 2, e):
            self.add_edge(u, v)
        return self

    def distance(self, u, v):
        q = [u]
        memo = {u: 0}
        while q:
            w = q.pop(0)
            if w == v:
                return memo[w]
            for x in self.next_to(w):
                if x not in memo:
                    memo[x] = memo[w] + 1
                    q.append(x)
        return float('inf')

def random_permutations(n, m, c):
    permutations = []
    for _ in range(c):
        permutation = random_permutation(n, m)
        permutations.append(permutation)
