def random_permutation(n, m):
    permutation = []
    for i in range(m):
        permutation.append(random.randint(0, n - i - 1))
    for i in range(m):
        for j in range(i + 1, m):
            if permutation[i] <= permutation[j]:
                permutation[j] += 1
    return permutation

