def find_partition_subsets(N, A):
    total_sum = sum(A)
    if total_sum % 2 != 0:
        return {"possible": False, "subsets": []}
    target = total_sum // 2
    A.sort()
    subsets = []

    def backtrack(start, current_sum, path):
        if current_sum == target:
            subsets.append(path.copy())
            return
        if current_sum > target:
            return
        for i in range(start, N):
            num = A[i]
            if current_sum + num > target:
                break  # Prune the rest as the list is sorted
            path.append(num)
            backtrack(i + 1, current_sum + num, path)
            path.pop()

    backtrack(0, 0, [])
    return {"possible": len(subsets) > 0, "subsets": subsets}
```

