def generate_char_range(start, stop, step=1):
    # Validate input characters
    if len(start) != 1 or len(stop) != 1:
        return "Invalid input"
    if not start.isalpha() or not stop.isalpha():
        return "Invalid input"
    if (start.isupper() and not stop.isupper()) or (start.islower() and not stop.islower()):
        return "Invalid input"

    # Validate step
    if step == 0 or not (-26 < step < 26):
        return "Invalid input"

    s_ord = ord(start)
    e_ord = ord(stop)

    if start == stop:
        return [start]

    # Check if step direction is compatible with start and stop order
    if (step > 0 and s_ord > e_ord) or (step < 0 and s_ord < e_ord):
        return []

    result = []
    current = s_ord

    if step > 0:
        while current <= e_ord:
            result.append(chr(current))
            current += step
    else:
        while current >= e_ord:
            result.append(chr(current))
            current += step

    return result
