def min_remove_to_make_valid(s):
    stack = []
    to_remove = set()
    for i, c in enumerate(s):
        if c == '(':
            stack.append(i)
        elif c == ')':
            if not stack:
                to_remove.add(i)
            else:
                stack.pop()
    # Add remaining unmatched '(' indices
    to_remove.update(stack)
    # Build the result string
    return ''.join(c for i, c in enumerate(s) if i not in to_remove)
