def is_confusing(n):
    rotation_map = {'0': '0', '1': '1', '8': '8', '6': '9', '9': '6'}
    s = str(n)
    rotated = []
    for c in reversed(s):
        if c not in rotation_map:
            return False
        rotated.append(rotation_map[c])
    rotated_str = ''.join(rotated)
    return rotated_str != s
