import math

def is_prime(n):
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    for i in range(3, int(math.isqrt(n)) + 1, 2):
        if n % i == 0:
            return False
    return True

def fermat_test(m, k):
    if m < 2:
        return False
    if m == 2 or m == 3:
        return True
    if m % 2 == 0:
        return False
    for a in range(2, 2 + k):
        if a >= m - 1:
            continue
        if pow(a, m - 1, m) != 1:
            return False
    return True

def find_fermat_witness(m):
    for a in range(2, m - 1 + 1):
        if pow(a, m - 1, m) != 1:
            return a
    return None

def solve(operation, N, k):
    if operation == 1:
        m = N + 1
        while True:
            if fermat_test(m, k):
                return {"first_possible_prime": m}
            m += 1
    else:
        m = N + 1
        while True:
            if not is_prime(m):
                witness = find_fermat_witness(m)
                return {"fermat_witness": witness}
            m += 1
