def format_operand(o):
    if isinstance(o, float):
        if o.is_integer():
            return str(int(o))
        else:
            return f"{o}"
    else:
        return o

def derivative(expression_type, operands):
    if expression_type == 'Constant':
        return '0'
    elif expression_type == 'Variable':
        var = operands[0]
        return '1' if var == 'x' else '0'
    elif expression_type == 'Plus':
        a, b = operands
        da = '1' if isinstance(a, str) and a == 'x' else '0'
        db = '1' if isinstance(b, str) and b == 'x' else '0'
        if da == '0' and db == '0':
            return '0'
        parts = []
        if da != '0':
            parts.append(da)
        if db != '0':
            parts.append(db)
        return ' + '.join(parts) if len(parts) > 0 else '0'
    elif expression_type == 'Minus':
        a, b = operands
        da = '1' if isinstance(a, str) and a == 'x' else '0'
        db = '1' if isinstance(b, str) and b == 'x' else '0'
        parts = []
        if da != '0':
            parts.append(da)
        if db != '0':
            parts.append(f"-{db}")
        if not parts:
            return '0'
        return ' '.join(parts)
    elif expression_type == 'Multiplication':
        a, b = operands
        a_str = format_operand(a)
        b_str = format_operand(b)
        da = 1 if isinstance(a, str) and a == 'x' else 0
        db = 1 if isinstance(b, str) and b == 'x' else 0
        term1 = f"{b_str}" if da else '0'
        term2 = f"{a_str}" if db else '0'
        parts = []
        if term1 != '0':
            parts.append(term1)
        if term2 != '0':
            parts.append(term2)
        return ' + '.join(parts) if parts else '0'
    elif expression_type == 'Division':
        a, b = operands
        a_str = format_operand(a)
        b_str = format_operand(b)
        da = 1 if isinstance(a, str) and a == 'x' else 0
        db = 1 if isinstance(b, str) and b == 'x' else 0
        numerator_parts = []
        if da:
            numerator_parts.append(f"{da}*{b_str}")
        if db:
            numerator_parts.append(f"-{a_str}*{db}")
        if not numerator_parts:
            return '0'
        numerator = ' '.join(numerator_parts)
        if len(numerator_parts) > 1 or '-' in numerator:
            numerator = f"({numerator})"
        denominator = f"({b_str})^2"
        return f"{numerator} / {denominator}"
    elif expression_type == 'Logarithm':
        u = operands[0]
        if isinstance(u, float):
            return '0'
        return '1 / x' if u == 'x' else '0'
    elif expression_type == 'Power':
        base, exponent = operands
        base_str = format_operand(base)
        exponent_str = format_operand(exponent)
        d_base = 1 if isinstance(base, str) and base == 'x' else 0
        d_exponent = 1 if isinstance(exponent, str) and exponent == 'x' else 0
        parts = []
        if d_base:
            exp_minus_1 = f"{exponent_str}-1"
            if ' ' in exponent_str:
                exp_minus_1 = f"({exp_minus_1})"
            parts.append(f"{exponent_str}*{base_str}^{exp_minus_1}")
        if d_exponent:
            parts.append(f"{base_str}^{exponent_str}*ln({base_str})")
        return ' + '.join(parts) if parts else '0'
    else:
        return '0'
